// A mix says which world holds each chapter. Two neighbouring chapters in
// one world join by that world's own move; in two worlds, by a dive.
import { CHAPTERS, type ChapterKey } from "./chapters.ts";

export type WorldId = "sheet" | "map" | "book";
export const WORLDS: readonly WorldId[] = ["sheet", "map", "book"];
export type Mix = Record<ChapterKey, WorldId>;

const whole = (w: WorldId) => Object.fromEntries(CHAPTERS.map((c) => [c.key, w])) as Mix;
export const WHOLE: Record<WorldId, Mix> = { sheet: whole("sheet"), map: whole("map"), book: whole("book") };

/** Eight comma-separated world ids in chapter order, or null. */
export function parseMix(text: string): Mix | null {
  const ids = String(text).split(",").map((x) => x.trim());
  if (ids.length !== CHAPTERS.length) return null;
  if (!ids.every((x) => (WORLDS as readonly string[]).includes(x))) return null;
  return Object.fromEntries(CHAPTERS.map((c, i) => [c.key, ids[i]])) as Mix;
}

export const formatMix = (m: Mix): string => CHAPTERS.map((c) => m[c.key]).join(",");

export type Seam = { from: ChapterKey; to: ChapterKey; kind: "within" | "dive" };

/** The joins between the chapters a site has, in order. */
export function seams(m: Mix, keys: readonly ChapterKey[]): Seam[] {
  const out: Seam[] = [];
  for (let i = 0; i + 1 < keys.length; i++) {
    const from = keys[i], to = keys[i + 1];
    out.push({ from, to, kind: m[from] === m[to] ? "within" : "dive" });
  }
  return out;
}

/** The chapters a world holds, in order. */
export const chaptersOf = (m: Mix, keys: readonly ChapterKey[], w: WorldId): ChapterKey[] => keys.filter((k) => m[k] === w);

/** The worlds a site uses, in the order they first appear. */
export function worldsOf(m: Mix, keys: readonly ChapterKey[]): WorldId[] {
  const out: WorldId[] = [];
  for (const k of keys) if (!out.includes(m[k])) out.push(m[k]);
  return out;
}
// The eight chapters of every site, in their fixed order, and the short
// words under each one, written from the person's data.
import type { Person, Work, Study } from "./person.ts";

export type ChapterKey = "hello" | "from" | "studied" | "worked" | "good" | "made" | "say" | "contact";

export const CHAPTERS: readonly { key: ChapterKey; title: string }[] = [
  { key: "hello", title: "Hello" },
  { key: "from", title: "Where from" },
  { key: "studied", title: "What I studied" },
  { key: "worked", title: "Where I've worked" },
  { key: "good", title: "What I'm good at" },
  { key: "made", title: "What I've made" },
  { key: "say", title: "What others say" },
  { key: "contact", title: "Get in touch" },
];

export const titleOf = (key: ChapterKey): string => CHAPTERS.find((c) => c.key === key)!.title;

/** "2020" when a job starts and ends in one year, "2021 to 2023", "2023 to now". */
export function yearText(w: Pick<Work, "from" | "to">): string {
  const a = Math.floor(w.from);
  const b = w.to == null ? "now" : Math.floor(w.to);
  return a === b ? String(a) : `${a} to ${b}`;
}

const studyText = (s: Study) => `${s.degree} in ${s.field}, ${s.place}, ${s.from} to ${s.to}`;

/** The words under each chapter asked for. Chapters not asked for are left out. */
export function captions(p: Person, keys: readonly ChapterKey[]): Partial<Record<ChapterKey, string>> {
  const write: Record<ChapterKey, () => string> = {
    hello: () => `${p.role}. ${p.line}`,
    from: () => p.places.map((x) => `${x.name} (${x.what})`).join(", then "),
    studied: () => p.study.map(studyText).join(". ") + ".",
    worked: () => p.work.map((w) => `${w.org}, ${yearText(w)}`).join(". ") + ".",
    good: () => p.skills.map((g) => g.group).join(", ") + ".",
    made: () => `${p.projects.length} ${p.projects.length === 1 ? "project" : "projects"}. Click one to open it.`,
    say: () => `From ${p.quotes.map((q) => q.who).join(", ")}.`,
    contact: () => `${p.contact.email}. ${p.seeking}.`,
  };
  const out: Partial<Record<ChapterKey, string>> = {};
  for (const k of keys) out[k] = write[k]();
  return out;
}

/** The words under each chapter: the person's own where they chose some, else written from their data. */
export function wordsFor(p: Person, keys: readonly ChapterKey[], chosen: Partial<Record<ChapterKey, string>> = {}): Partial<Record<ChapterKey, string>> {
  const out = captions(p, keys);
  for (const k of keys) {
    const own = chosen[k]?.trim();
    if (own) out[k] = own;
  }
  return out;
}

